 "content": "def _decode(grid, diagonal):
    """Recover the shortest fully observed periodic coloring on a diagonal index."""
    h, w = len(grid), len(grid[0])
    values = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color == 0:
                continue
            index = r + c if diagonal == "sum" else c - r
            if index in values and values[index] != color:
                return None
            values[index] = color
    if not values:
        return None

    for period in range(1, len(values) + 1):
        motif = {}
        for index, color in values.items():
            phase = index % period
            if phase in motif and motif[phase] != color:
                break
            motif[phase] = color
        else:
            if len(motif) == period:
                return period, motif
    return None


def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates = []
    for diagonal in ("sum", "diff"):
        decoded = _decode(grid, diagonal)
        if decoded:
            period, motif = decoded
            candidates.append((len(motif), -period, diagonal, period, motif))
    if not candidates:
        raise ValueError("no fully determined periodic diagonal motif")

    # If both orientations encode a constant field either yields the same grid;
    # otherwise the conflicting orientation is rejected by _decode.
    _, _, diagonal, period, motif = max(candidates)
    return [[motif[((r + c) if diagonal == "sum" else (c - r)) % period]
             for c in range(w)] for r in range(h)]


